			name:          "string value",
			redactionList: []string{"William"},
			logFields:     logrus.Fields{"Description": "His name is William"},
			expected:      logrus.Fields{"Description": "His name is [REDACTED]"},
			description:   "William should have been redacted, but was not.",
		},
		{
			name:          "map keys and values",
			redactionList: []string{"Password"},
			logFields: logrus.Fields{"details": map[string]string{
				"Password": "secret", "note": "contains Password",
			}},
			expected: logrus.Fields{"details": map[string]string{
				"Password": "[REDACTED]", "note": "contains [REDACTED]",
			}},
		},
		{
			name:          "nested maps and formatted values",
			redactionList: []string{"Secret|123"},
			logFields: logrus.Fields{"details": map[string]interface{}{
				"nested": map[string]interface{}{"Secret": "secret", "count": 123},
				"safe":   "unchanged",
			}},
			expected: logrus.Fields{"details": map[string]interface{}{
				"nested": map[string]interface{}{"Secret": "[REDACTED]", "count": "[REDACTED]"},
				"safe":   "unchanged",
			}},
		},
		{
			name:          "nil values in nested maps",
			redactionList: []string{"Secret"},
			logFields: logrus.Fields{"details": map[string]interface{}{
				"empty": nil,
				"nested": map[string]interface{}{
					"empty": nil, "Secret": nil, "nilMap": map[string]interface{}(nil),
				},
			}},
			expected: logrus.Fields{"details": map[string]interface{}{
				"empty": "<nil>",
				"nested": map[string]interface{}{
					"empty": "<nil>", "Secret": "[REDACTED]", "nilMap": map[string]interface{}(nil),
				},
			}},
		},
		{
			name:          "other value uses default formatting",
			redactionList: []string{"secret"},
			logFields:     logrus.Fields{"details": struct{ Value string }{"secret"}},
			expected:      logrus.Fields{"details": "{[REDACTED]}"},
		},
	}

	for _, test := range tests {
		fn := func(t *testing.T) {
			logEntry := &logrus.Entry{
				Data: test.logFields,
			}
			h = &Hook{RedactionList: test.redactionList}
			err := h.Fire(logEntry)

			assert.Nil(t, err)
			assert.Equal(t, test.expected, logEntry.Data)
		}
		t.Run(test.name, fn)
	}
}

// Test that any occurrence of a redaction pattern
// in the entry's Message field is redacted.
func TestEntryMessage(t *testing.T) {
	logEntry := &logrus.Entry{
		Message: "Secret Password: password123!",
	}
	h = &Hook{RedactionList: []string{`(Password: ).*`}}
	err := h.Fire(logEntry)

	assert.Nil(t, err)
	assert.Equal(t, "Secret Password: [REDACTED]", logEntry.Message)
}
